import { Color } from "../../core/math/color.js";
const COLOR_RED = Object.freeze(new Color(1, 0.3, 0.3));
const COLOR_GREEN = Object.freeze(new Color(0.3, 1, 0.3));
const COLOR_BLUE = Object.freeze(new Color(0.3, 0.3, 1));
const COLOR_YELLOW = Object.freeze(new Color(1, 1, 0.5));
const COLOR_AMBER = Object.freeze(new Color(1, 0.75, 0.3));
const COLOR_CYAN = Object.freeze(new Color(0.3, 0.85, 1));
const COLOR_MAGENTA = Object.freeze(new Color(1, 0.45, 0.9));
const COLOR_GRAY = Object.freeze(new Color(0.5, 0.5, 0.5, 0.5));
const COLOR_BACKDROP = Object.freeze(new Color(0.05, 0.055, 0.07, 0.6));
const color4from3 = (color, a) => {
  return new Color(color.r, color.g, color.b, a);
};
export {
  COLOR_AMBER,
  COLOR_BACKDROP,
  COLOR_BLUE,
  COLOR_CYAN,
  COLOR_GRAY,
  COLOR_GREEN,
  COLOR_MAGENTA,
  COLOR_RED,
  COLOR_YELLOW,
  color4from3
};
